[2026-11-20] rc:4646507851 inline on src/test/kernel/test_kernel.cpp by pzafonte (contributor) (edited 2026-11-20):
Genuinely curious, would it make sense to add a test_kernel case for it? Destroying the chainman triggers a flush, and replacing `blocks/blk00000.dat` (or `rev00000.dat`) with a directory is enough to make that flush fail. I ran it on 8a5934f and the handler got `BLOCK_FILE_FLUSH_FAILED` (0) and `UNDO_FILE_FLUSH_FAILED` (1).

test_kernel.cpp diff

```diff
+class FlushErrorRecorder : public TestKernelNotifications
+{
+public:
+    std::vector<FlushError> m_errors;
+    void FlushErrorHandler(FlushError error) override { m_errors.push_back(error); }
+};
+
+static std::vector<FlushError> DestroyWithUnopenableFile(const std::string& name, const std::string& file)
+{
+    auto test_directory{TestDirectory{name}};
+    auto notifications{std::make_shared<FlushErrorRecorder>()};
+    auto context{create_context(notifications, ChainType::REGTEST)};
+    auto chainman{create_chainman(
+        test_directory, /*reindex=*/false, /*wipe_chainstate=*/false,
+        /*block_tree_db_in_memory=*/true, /*chainstate_db_in_memory=*/true, context)};
+    for (size_t i{0}; i < 3; i++) {
+        Block block{hex_string_to_byte_vec(REGTEST_BLOCK_DATA[i])};
+        bool new_block{false};
+        chainman->ProcessBlock(block, &new_block);
+        BOOST_REQUIRE(new_block);
+    }
+    const fs::path path{test_directory.m_directory / "blocks" / fs::u8path(file)};
+    BOOST_REQUIRE(fs::exists(path));
+    fs::rename(path, path + ".moved");
+    BOOST_REQUIRE(fs::create_directory(path));
+    BOOST_REQUIRE(notifications->m_errors.empty());
+    chainman.reset();
+    return notifications->m_errors;
+}
+
+static int RawValue(FlushError error) { return int{static_cast<std::underlying_type_t<FlushError>>(error)}; }
+
+BOOST_AUTO_TEST_CASE(btck_flush_error_block_file)
+{
+    const auto errors{DestroyWithUnopenableFile("flush_error_block_file", "blk00000.dat")};
+    BOOST_REQUIRE_EQUAL(errors.size(), 1U);
+    BOOST_CHECK(errors[0] == FlushError::BLOCK_FILE_FLUSH_FAILED);
+    BOOST_CHECK_EQUAL(RawValue(errors[0]), 0);
+}
+
+BOOST_AUTO_TEST_CASE(btck_flush_error_undo_file)
+{
+    const auto errors{DestroyWithUnopenableFile("flush_error_undo_file", "rev00000.dat")};
+    BOOST_REQUIRE_EQUAL(errors.size(), 1U);
+    BOOST_CHECK(errors[0] == FlushError::UNDO_FILE_FLUSH_FAILED);
+    BOOST_CHECK_EQUAL(RawValue(errors[0]), 1);
+}
```
